usage:
Enable the Better Auth Stripe plugin first, then wire onSelectPlan to checkout via the Better Auth Stripe client:

```ts
import { createAuthClient } from 'better-auth/client'
import { stripeClient } from '@better-auth/stripe/client'
const client = createAuthClient({ baseURL: `${apiUrl()}/auth`, plugins: [stripeClient({ subscription: true })] })

// in the page:
const upgrade = useMutation({ mutationFn: (plan: string) => client.subscription.upgrade({ plan, successUrl: '/app', cancelUrl: '/pricing' }) })
<PricingTable plans={plans} currentPlanId={active?.plan} onSelectPlan={upgrade.mutate} />
```
